  if ([facts, vectors].some((item, index) => item.hole?.state === "missing"
    && item.indexedThrough > (index === 0 ? scope.factsThrough : scope.vectorsThrough))) {
    await ctx.scheduler.runAfter(0, refreshRef, { reference });
